}
------------ define ------------

function UICultivateMainEquipInfoNode:__init()
    self.nodeEnvList = {}
end

function UICultivateMainEquipInfoNode:__delete()
    self.clickEquipNodeGroupAction = nil
    self.clickUninstallButtonAction = nil
end

function UICultivateMainEquipInfoNode:Awake()
    KTool.SetActive(self.ButtonGroup1.gameObject, false)
    KTool.SetActive(self.ButtonGroup2.gameObject, true)

    SetButtonAction(self.DiySuitButton.gameObject, Bind(self, self.OnClickDiySuitButtonAction))
    SetButtonAction(self.UninstallButton.gameObject, Bind(self, self.OnClickUninstallButtonAction))
end

function UICultivateMainEquipInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function UICultivateMainEquipInfoNode:InitData(cardDojo, part)
    self.cardDojo = cardDojo
    self:InitEquipIdList(cardDojo)
    self.originalEquipmentCoreId = checkNumber(cardDojo.equipmentCore)
    self.selectPart = part
end

---InitCurEquipIdList
---初始化当前装备id列表
function UICultivateMainEquipInfoNode:InitEquipIdList(cardDojo)
    local equipIdList = {0, 0, 0, 0}
    local GetEquipIdKeyByPart = EquipUtils.GetEquipIdKeyByPart
    for i = 1, Constants.CardEquipmentNo do
        local key = GetEquipIdKeyByPart(i)
        --- equipment1 equipment2
        equipIdList[i] = checkNumber(cardDojo[key])
    end

    self.originalEquipIdList = clone(equipIdList)
    self.equipIdList = equipIdList
end

