---RefreshUI
---@param cardDojo CardDojo
function UICultivateMainEquipInfoNode:RefreshUI(cardDojo, part)

    self:InitData(cardDojo, part)
    xTry(function()
        self:RefreshEquipNodeGroup(cardDojo)
        self:RefreshSuitDescAndAttrNode(cardDojo)

    end)

end

---RefreshEquipNodes
---刷新拥有的装备
function UICultivateMainEquipInfoNode:RefreshEquipNodeGroup(cardDojo)
    ---@type UICultivateEquipAndCoreGroupNode
    local mbEnv = self:GetEnvByType(self.EquipNodeGroup, EnvType.EquipAndCoreGroup)
    if mbEnv == nil then return end

    mbEnv:SetCallback(Bind(self, self.OnClickEditEquipAction))
    mbEnv:RefreshUI(cardDojo, true)
    mbEnv:RefreshCardIcon(cardDojo)
    mbEnv:RefreshSelectStateByPart(self.selectPart, true)
end

---RefreshSuitDescAndAttrNode
---刷新套装描述和属性节点
function UICultivateMainEquipInfoNode:RefreshSuitDescAndAttrNode(cardDojo, isUpdateData)
    ---@type UICultivateEquipSuitDescAndAttrNodeMB
    local mbEnv = self:GetEnvByType(self.SuitDescAndAttrNode, EnvType.SuitDescAndAttrNode)
    if mbEnv == nil then return end
    if isUpdateData then
        self:InitData(cardDojo)
    end
    mbEnv:RefreshUI(self.equipIdList, cardDojo.equipmentCore, cardDojo)
end


function UICultivateMainEquipInfoNode:RefreshEquipNodeSelectState(part, isSelect)
    ---@type UICultivateEquipAndCoreGroupNode
    local mbEnv = self:GetEnvByType(self.EquipNodeGroup, EnvType.EquipAndCoreGroup)
    if mbEnv == nil then return end
    self.selectPart = part
    mbEnv:RefreshSelectStateByPart(part, isSelect)
end

function UICultivateMainEquipInfoNode:RefreshEquipNodeGroupByPart(part, dojo, equipmentCoreDojo)
    ---@type UICultivateEquipAndCoreGroupNode
    local mbEnv = self:GetEnvByType(self.EquipNodeGroup, EnvType.EquipAndCoreGroup)
    if mbEnv == nil then return end
    mbEnv:RefreshNodeByPart(part, dojo, equipmentCoreDojo)

end

