function UICultivateMainEquipInfoNode:SetClickEquipNodeGroupAction(cb)
    self.clickEquipNodeGroupAction = cb
end

function UICultivateMainEquipInfoNode:SetClickUninstallButtonAction(cb)
    self.clickUninstallButtonAction = cb
end

function UICultivateMainEquipInfoNode:GetEnvByType(node, envType)
    local mbEnv = self.nodeEnvList[envType]
    if isNull(mbEnv) then
        mbEnv = CfUtils.GetLuaScr(node, EnvPathConfig[envType])
    end
    return mbEnv
end

