function UICultivateMainEquipInfoNode:OnClickEditEquipAction(part)
    if self.clickEquipNodeGroupAction then
        self.clickEquipNodeGroupAction(part)
    end
end

function UICultivateMainEquipInfoNode:OnClickDiySuitButtonAction()
    Events.Broadcast(Constants.EventNames.UICultivateEquipSaveUiState)
    local ids = GameUtils.GetAllExcludeIds()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateEquipDiySuitDialog,
                          parameters = {
                              playerCardId = self.cardDojo.id,
                              part = self.part
                          }
    }, ids)
end

function UICultivateMainEquipInfoNode:OnClickUninstallButtonAction()
    if self.clickUninstallButtonAction then
        self.clickUninstallButtonAction()
    end
end

